public static container runableForAsyncCall(container _params)
{
    container conRet = conNull();
    int maxRuntimeInMinutes = conPeek(_params, 1);
    NoYes deleteActualData = conPeek(_params, 2);
    NoYes runWithoutAction = conPeek(_params, 3);
    NDXTokenizerExcludesFromAX2009 nDXTokenizerExcludesFromAX2009 = NDXTokenizerExcludesFromAX2009::construct();
    nDXTokenizerExcludesFromAX2009.ParmDeleteActualData(deleteActualData);
    nDXTokenizerExcludesFromAX2009.ParmRunWithoutAction(runWithoutAction);
    nDXTokenizerExcludesFromAX2009.ReadContractsFromQueue(maxRuntimeInMinutes);
    return conRet;
}

