/// <summary>
/// PaffH 04.02.23
/// </summary>
/// <param name = "_maxRuntimeInMinutes">int</param>
public void readContractsFromQueue(int _maxRuntimeInMinutes = 0)
{
    maxRuntimeInMinutes = _maxRuntimeInMinutes;

    NDXTokenizerExcludes nDXTokenizerExcludes;
    boolean loopOK = true;
    int recCount1, recCount2, recCount3, countReadFromQueue, countRuns;
    NDXTokenizerExcludesContract nDXTokenizerExcludesContract, nDXTokenizerExcludesContractLast;
    TokenizerExcludesFromAX2009 tokenizerExcludesFromAX2009 = new TokenizerExcludesFromAX2009(connectionString, azureQueueName);

    int sleepDuration = 1000;
    secStart = NDXHelperCommon::timeNow();
    int secStartRun = secStart;
    int secEnd, diffSec;
    str errInfo;
    NDXDataTransferErrorClass dataTransferError = NDXDataTransferErrorClass::construct(tableNum(NDXTokenizerExcludes));
    recCount1 = 0;
    recCount2 = 0;
    recCount3 = 0;
    countReadFromQueue = 0;
    countRuns = 0;
    int runtimeInMinutes;
    nDXTokenizerExcludesContractLast = null;
    isReadingFromQueue = true;
    info(strFmt('Start : [%1]', NDXHelperCommon::seconds2Str()));
    if (deleteActualData == NoYes::Yes)
    {
        this.deleteActualData();
        dataTransferError.deleteExistingLog();
    }
    while (loopOK)
    {
        nDXTokenizerExcludes = null;
        nDXTokenizerExcludesContract = tokenizerExcludesFromAX2009.Receive1MessageValuesD365FO(true).Contract;
        if (runWithoutAction == NoYes::Yes)
        {
            if (nDXTokenizerExcludesContract == null)
            {
                break;
            }
            else
            {
                continue;
            }
        }


        if (nDXTokenizerExcludesContract == null && nDXTokenizerExcludesContractLast == null)
        {
            secEnd = NDXHelperCommon::timeNow();
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }

        ++countReadFromQueue;
        if (nDXTokenizerExcludesContract == null && nDXTokenizerExcludesContractLast != null)
        {
            nDXTokenizerExcludesContractLast = null;
            ++countRuns;
            secEnd = NDXHelperCommon::timeNow();
            diffSec = secEnd - secStartRun;
            Info(strFmt('%1.) Dauer: [%2]', countRuns, NDXHelperCommon::seconds2Str(diffSec)));
            Info(strFmt('%1.) Azure-Queue Lesevorgänge: [%2]', countRuns, countReadFromQueue));
            Info(strFmt('%1.) Anzahl DS: Artikel[%2] [%3][%4]', countRuns, recCount1, recCount2, recCount3));
            runtimeInMinutes = real2int((secEnd - secStart) / 60);
            if (maxRuntimeInMinutes != 0 && runtimeInMinutes >= maxRuntimeInMinutes)
            {
                break;
            }
            else
            {
                sleep(sleepDuration);
                continue;
            }
        }
        else
        {
            nDXTokenizerExcludesContractLast = nDXTokenizerExcludesContract;
            secStartRun = NDXHelperCommon::timeNow();
        }

        // read data from: nDXTokenizerExcludes - Contract
        IEnumerable tList = nDXTokenizerExcludesContract.nDXTokenizerExcludesTableContract;
        IEnumerator enum = tList.GetEnumerator();
        while (enum.moveNext())
        {
            ++recCount1;
            errInfo = '';
            NDXTokenizerExcludesTableContract nDXTokenizerExcludesTableContract = enum.current;

            if (nDXTokenizerExcludesTableContract.toExcludeFrom != '')
            {
                nDXTokenizerExcludes = NDXTokenizerExcludes::findOrCreate(nDXTokenizerExcludesTableContract.toExcludeFrom, false);
                nDXTokenizerExcludes.ToInclude = nDXTokenizerExcludesTableContract.toInclude;
                nDXTokenizerExcludes.TokenizerExcludeType = nDXTokenizerExcludesTableContract.TokenizerExcludeType;
                nDXTokenizerExcludes.Priority = nDXTokenizerExcludesTableContract.Priority;
                ttsbegin;
                nDXTokenizerExcludes.write();
                ttscommit;
            }
            else
            {
                continue;
            }
        }
    }
    dataTransferError.endError();
    secEnd = NDXHelperCommon::timeNow();
    Info(strFmt('Gesamtlaufzeit: [%1]', NDXHelperCommon::seconds2Str(secEnd - secStart)));
    isReadingFromQueue = false;
}
